        vm.roll(blk);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Invariant: after a successful call, pastBlockTime equals the call's block.timestamp.
        assertTrue(c.pastBlockTime() == ts);
    }
}

