pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 jump) public {
        ts = bound(ts, 1000, 1e18);
        jump = bound(jump, 1, 1e12);

        vm.deal(address(this), 10 ether);
        vm.warp(ts);

        vm.prank(address(this));
        c.fallback{value: 10 ether, gas: 100000}();

        // move to a LATER timestamp within the SAME block
        vm.warp(ts + jump);

        bool ok2;
        vm.prank(address(this));
        try c.fallback{value: 10 ether, gas: 100000}() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // In the same block, no later timestamp can exceed the recorded
        // pastBlockTime (= that block's timestamp), so the second call
        // must revert. The mutant stores block.number, so it succeeds
        // whenever block.timestamp > block.number (fuzzer finds this).
        assertTrue(!ok2);
    }
}

