contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);
        uint256 n = 15 + (seed % 1000) * 15; // block number divisible by 15
        vm.roll(n);
        vm.warp(n);
        vm.deal(actor, 10 ether);
        uint256 before = actor.balance;
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // Invariant: a winning caller is paid the full contract balance and ends
        // with the same balance they started with.
        assertEq(actor.balance, before);
    }
}

