pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0));
        vm.warp(t);

        // first call at timestamp t succeeds on both versions
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        uint256 p1 = c.pastBlockTime();
        assertEq(p1, t);

        // second call at the SAME timestamp t must revert (P),
        // but succeeds on the mutant (M)
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // general rule: pastBlockTime strictly increases, so a second
        // same-timestamp call can never succeed on the reference
        assertTrue(!ok && c.pastBlockTime() == p1);
    }
}

