pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 badAmount, address actor) public {
        vm.assume(ts > 0);
        vm.assume(badAmount != 10 ether);
        vm.assume(actor != address(0));

        vm.warp(ts);
        vm.deal(actor, badAmount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: badAmount}("");

        // Rule: a reverting call must leave pastBlockTime unchanged.
        // Reference: call reverts (ok == false) and pastBlockTime stays 0 (!= ts).
        // Mutant: pastBlockTime was set to ts before the requires, so getter returns ts.
        assertTrue(!ok && c.pastBlockTime() != ts);
    }
}

